class Solution {
public:
    int countQuadruplets(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int, int> diffCount;
        int ans = 0;
        for (int b = n - 2; b >= 1; b--) {
            int c = b + 1;
            for (int d = c + 1; d < n; d++) {
                diffCount[nums[d] - nums[c]]++;
            }
            for (int a = 0; a < b; a++) {
                ans += diffCount[nums[a] + nums[b]];
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countQuadruplets(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> diffCount = new HashMap<>();
        int ans = 0;
        for (int b = n - 2; b >= 1; b--) {
            int c = b + 1;
            for (int d = c + 1; d < n; d++) {
                int diff = nums[d] - nums[c];
                diffCount.put(diff, diffCount.getOrDefault(diff, 0) + 1);
            }
            for (int a = 0; a < b; a++) {
                int sum = nums[a] + nums[b];
                ans += diffCount.getOrDefault(sum, 0);
            }
        }
        return ans;
    }
}

